  rating: ['rating', 'feedback-thumbs'],
  done: ['success-state', 'toast', 'live-validation'],
  share: ['share-icon', 'external-link'],
  transition: ['shared-element', 'easing', 'spring'],
  'text-motion': ['streaming', 'marquee', 'typing-indicator'],
  'button-state': ['hover', 'button-hierarchy', 'icon-button'],
  onboarding: ['splash', 'coachmark', 'permission-prompt', 'social-login', 'page-dots'],
  date: ['date-picker', 'time-picker', 'calendar-view'],
  'list-view': ['list-item', 'card', 'table', 'masonry', 'carousel', 'infinite-scroll', 'pagination', 'load-more'],
  chart: ['chart', 'stat-card', 'progress-circular'],
  type: ['truncation', 'blockquote'],
