/** 이 서랍에 들어 있는 카드 (원래 서랍 + 주제로 함께 보여 주는 카드) */
export const inDrawer = (d: DrawerId) => [...ENTRIES.filter((e) => e.drawer === d), ...(ALSO[d] ?? []).map((id) => byId.get(id)!)]

// ─── 찾기 ───
const CHO = 'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ'

/** 한글을 초성으로 바꿔요: 토스트 → ㅌㅅㅌ */
export function choseong(s: string) {
  return [...s].map((c) => {
    const code = c.charCodeAt(0) - 0xac00
    return code >= 0 && code < 11172 ? CHO[Math.floor(code / 588)] : c
  }).join('')
}

/** 받침이 있으면 앞 조사를, 없으면 뒤 조사를: josa('툴팁', '이에요', '예요') → '툴팁이에요' */
export function josa(word: string, withFinal: string, without: string) {
  const c = word.charCodeAt(word.length - 1) - 0xac00
  return word + (c >= 0 && c < 11172 && c % 28 !== 0 ? withFinal : without)
}

const norm = (s: string) => s.toLowerCase().replace(/[\s·_\-]/g, '')

/** 이름 · 영어 이름 · 다른 이름 · 모양 설명 · 초성으로 찾아요. 이름이 맞을수록 앞에 와요. */
export function search(query: string, list: Entry[] = ENTRIES, alts = true): Entry[] {
  const q = norm(query)
  if (!q) return list
  const onlyCho = /^[ㄱ-ㅎ]+$/.test(q)
  const scored = list.map((e) => {
    const names = [e.ko, e.en, ...(e.aliases ?? [])].map(norm)
    let score = 0
    if (onlyCho) score = names.some((n) => choseong(n).includes(q)) ? 3 : 0
    else if (names.some((n) => n === q)) score = 5
    else if (names.some((n) => n.startsWith(q))) score = 4
    else if (names.some((n) => n.includes(q))) score = 3
    else if (norm(e.hint).includes(q)) score = 2
    else if (norm(e.desc).includes(q)) score = 1
    return { e, score }
  })
  const found = scored.filter((s) => s.score > 0).sort((a, b) => b.score - a.score).map((s) => s.e)
  // 같은 뜻의 다른 말로도 찾아요 (팝업 → 모달 등). 원래 결과 뒤에 붙여요.
  const alt = alts ? SYNONYMS[q] : undefined
  if (!alt) return found
  // 한 번만 펼쳐요 (‘별점 → 별점’처럼 자기 자신을 가리켜도 끝없이 돌지 않게)
  const more = alt.flatMap((w) => search(w, list, false)).filter((e) => !found.includes(e))
  return [...found, ...new Set(more)]
}

